import kotlinx.html.*

fun FlowContent.card() {
    div {
        attributes["data-on:click"] = "@clipbord('x')"
        attributes["data-persist"] = ""
    }
}

import kotlinx.html.*

fun FlowContent.card(name: String, handler: String) {
    div {
        attributes[name] = "@clipbord('x')"
        attributes["data-on:click"] = handler
    }
}

import io.github.markusaugust.streamlord.html.*

fun FlowContent.v() {
    div {
        dataInit(get("/x"))
        dataIndicator("busy")
    }
    div {
        dataInit("@post('/y')")
        span { dataIndicator("inner") }
        dataIndicator("late")
    }
    div {
        dataIndicator("first")
        dataInit(get("/x"))
    }
    div {
        dataInit("@get('/z')") { delay = 500.milliseconds }
        dataIndicator("waits")
    }
}

import io.github.markusaugust.streamlord.html.*

fun FlowContent.v() {
    div {
        dataShow("")
        dataOnClick(" ")
        dataText("\$a")
    }
}
